node -e "
const fs = require('fs');
const content = fs.readFileSync('specs/hal-engine-session-resume/spec.md', 'utf8');
const lines = content.split('\n');
const newContent = content.replace(/#L(\d+)/g, (match, p1) => {
  const lineNum = parseInt(p1);
  if (lineNum >= 180) return '#L' + (lineNum - 14);
  return match;
});
fs.writeFileSync('specs/hal-engine-session-resume/spec.md', newContent);
"
